import CryptoKit
import XCTest
@testable import ConetChatSDK

#if BEAMIO_TEST_HOOKS

/// `pgpIdentityCreate` up to the local pending key. The chain is a mock
/// (AddressPGPChain.transport), the registration is a fake, and the key is generated by the X-19 v4 wrapper, so the class
/// runs only where the framework is linked (iOS builds with Vendor/X19.xcframework). No test reaches a chain.
final class PGPIdentityCreateTests: XCTestCase {
	private let account = "0x9858effd232b4033e47d90003d41ec34ecaeda94"
	private let contract = "0x684b0ac760cEE9c9b85de36d69746420648Cf9e2"

	struct MockChain {
		var exists = false
		var publicArmor = ""
		var backup = ""
		var readable = true
	}

	final class FakeRegistration: BeamioPGPIdentityCreate.Registering {
		var result: Result<Void, Error> = .success(())
		var calls: [(eoa: String, publicArmor: String, idempotencyKey: String, seen: String)] = []
		func register(eoa: String, publicArmor: String, idempotencyKey: String, seen: String) -> Result<Void, Error> {
			calls.append((eoa, publicArmor, idempotencyKey, seen))
			return result
		}
	}

	private var chain = MockChain()
	private var savedTransport: ((URL, Data) -> Result<Data, Error>)!
	private var savedRegistration: BeamioPGPIdentityCreate.Registering?
	private var savedGenerate: ((String) -> Result<(privateArmor: String, publicArmor: String), Error>)!
	private var fake = FakeRegistration()
	private var identityEvents: [[String: Any]] = []
	private var chainReads = 0
	private var generatedCount = 0

	override func setUp() {
		super.setUp()
		savedTransport = AddressPGPChain.transport
		AddressPGPChain.configuration = AddressPGPChain.Configuration(
			contract: contract, chainId: 224422, rpcURL: URL(string: "https://rpc.example.invalid/")!
		)
		AddressPGPChain.transport = { [unowned self] _, body in self.answer(body) }
		BeamioChatPgpKeychain.memory = BeamioChatPgpKeychain.MemoryRecords()
		// The first-identity judgement is native (frozen protocol §13). These tests are about the create flow, so the chain is judged unregistered here; the
		// judgement itself is tested in FirstIdentityTests.
		BeamioFirstIdentity.chainProbe = { _ in .unregistered }
		savedRegistration = BeamioPGPIdentityCreate.registration
		savedGenerate = BeamioPGPIdentityCreate.generateKeyPair
		fake = FakeRegistration()
		BeamioPGPIdentityCreate.registration = fake
		BeamioPGPIdentityCreate.resetCompletedIdentities()
		BeamioPGPIdentityCreate.resetInFlightIdentities()
		chain = MockChain()
	}

	override func tearDown() {
		AddressPGPChain.transport = savedTransport
		AddressPGPChain.configuration = nil
		BeamioPGPIdentityCreate.registration = savedRegistration
		BeamioPGPIdentityCreate.generateKeyPair = savedGenerate
		BeamioChatPgpKeychain.memory = nil
		BeamioFirstIdentity.chainProbe = { AddressPGPChain.chainStatus(eoa: $0) }
		super.tearDown()
	}

	// MARK: - Mock node

	private func word(_ n: Int) -> [UInt8] {
		[UInt8](repeating: 0, count: 24) + withUnsafeBytes(of: UInt64(n).bigEndian) { Array($0) }
	}

	private func encodedString(_ s: String) -> [UInt8] {
		let data = Array(s.utf8)
		return word(data.count) + data + [UInt8](repeating: 0, count: (32 - data.count % 32) % 32)
	}

	private func hex(_ bytes: [UInt8]) -> String {
		"0x" + bytes.map { String(format: "%02x", $0) }.joined()
	}

	private func answer(_ body: Data) -> Result<Data, Error> {
		guard let object = try? JSONSerialization.jsonObject(with: body) as? [String: Any],
		      let method = object["method"] as? String
		else { return .failure(AddressPGPChain.ReadError.malformed) }
		if !chain.readable { return .failure(AddressPGPChain.ReadError.transport("timeout")) }
		let result: Any
		switch method {
		case "eth_blockNumber":
			result = "0x1f4"
		case "eth_call":
			let call = ((object["params"] as? [Any])?.first as? [String: Any]) ?? [:]
			let data = (call["data"] as? String) ?? ""
			if data.hasPrefix(hex(AddressPGPChain.selector("_pgpKeys(address)"))) {
				let s1 = encodedString(""), s2 = encodedString(chain.publicArmor), s3 = encodedString("")
				let head = 128
				let raw = word(head) + word(head + s1.count) + word(head + s1.count + s2.count) + word(chain.exists ? 1 : 0)
				result = hex(raw + s1 + s2 + s3)
			} else {
				result = hex(word(32) + encodedString(chain.backup))
			}
		default:
			return .failure(AddressPGPChain.ReadError.rpc("unsupported"))
		}
		return .success(try! JSONSerialization.data(withJSONObject: ["jsonrpc": "2.0", "id": 1, "result": result]))
	}

	private func requireFramework() throws {
		try XCTSkipUnless(BeamioPGPNative.linked, "X-19 framework not linked in this build")
	}

	// MARK: - Prepare (the command)

	func testAFirstIdentityIsPreparedAsFirst() throws {
		try requireFramework()
		chain = MockChain(exists: false, publicArmor: "", backup: "", readable: true)
		XCTAssertEqual(BeamioPGPIdentityCreate.prepare(eoa: account, idempotencyKey: "idem-1"), .ready(.first))
		let pending = try XCTUnwrap(BeamioChatPgpKeychain.loadPending(eoa: account))
		XCTAssertEqual(pending.privateArmor, "", "prepared, no key yet")
		XCTAssertEqual(pending.idempotencyKey, "idem-1")
		XCTAssertFalse(pending.seen.isEmpty)
	}

	func testARecordWithoutABackupIsPreparedAsReplace() throws {
		try requireFramework()
		chain = MockChain(exists: true, publicArmor: "-----BEGIN PGP PUBLIC KEY BLOCK-----\nsynthetic\n-----END PGP PUBLIC KEY BLOCK-----", backup: "", readable: true)
		XCTAssertEqual(BeamioPGPIdentityCreate.prepare(eoa: account, idempotencyKey: "idem-r"), .ready(.replace))
	}

	func testAReadFailureIsPGPSourceUnavailableAndNothingIsPending() throws {
		try requireFramework()
		chain = MockChain(readable: false)
		XCTAssertEqual(BeamioPGPIdentityCreate.prepare(eoa: account, idempotencyKey: "idem-u"), .failed("pgp_source_unavailable"))
		XCTAssertNil(BeamioChatPgpKeychain.loadPending(eoa: account))
	}

	func testAnotherIdempotencyKeyWhilePendingIsPendingExists() throws {
		try requireFramework()
		chain = MockChain()
		XCTAssertEqual(BeamioPGPIdentityCreate.prepare(eoa: account, idempotencyKey: "idem-a"), .ready(.first))
		XCTAssertEqual(BeamioPGPIdentityCreate.prepare(eoa: account, idempotencyKey: "idem-b"), .failed("pending_exists"))
	}

	func testAnEmptyKeyIsBadRequest() throws {
		try requireFramework()
		XCTAssertEqual(BeamioPGPIdentityCreate.prepare(eoa: account, idempotencyKey: ""), .failed("bad_request"))
	}

	// MARK: - Confirm (after the native panel)

	func testConfirmGeneratesStoresAndRegistersThenWritesTheRecord() throws {
		try requireFramework()
		chain = MockChain()
		XCTAssertEqual(BeamioPGPIdentityCreate.prepare(eoa: account, idempotencyKey: "idem-c"), .ready(.first))
		XCTAssertEqual(BeamioPGPIdentityCreate.confirm(eoa: account, idempotencyKey: "idem-c"), .ok)
		XCTAssertEqual(fake.calls.count, 1)
		let sent = try XCTUnwrap(fake.calls.first)
		XCTAssertTrue(sent.publicArmor.hasPrefix("-----BEGIN PGP PUBLIC KEY BLOCK-----"))
		XCTAssertFalse(sent.publicArmor.contains("PRIVATE"), "only the public armor is registered")
		XCTAssertEqual(sent.idempotencyKey, "idem-c")
		let stored = try XCTUnwrap(BeamioChatPgpKeychain.load(eoa: account))
		XCTAssertEqual(stored.publicKeyArmor, sent.publicArmor)
		XCTAssertTrue(stored.privateKeyArmor.contains("PRIVATE KEY BLOCK"))
		XCTAssertNil(BeamioChatPgpKeychain.loadPending(eoa: account), "the pending key is cleared after the write is read back")
	}

	func testWithoutARegistrationTheGeneratedKeyWaitsAndSurvivesTheCall() throws {
		try requireFramework()
		chain = MockChain()
		// The key is generated while the write path is approved (the seam is set); the registration then goes away (applies to prepare).
		XCTAssertEqual(BeamioPGPIdentityCreate.prepare(eoa: account, idempotencyKey: "idem-w"), .ready(.first))
		BeamioPGPIdentityCreate.registration = nil
		XCTAssertEqual(BeamioPGPIdentityCreate.confirm(eoa: account, idempotencyKey: "idem-w"), .waitingRegistration)
		let pending = try XCTUnwrap(BeamioChatPgpKeychain.loadPending(eoa: account))
		XCTAssertFalse(pending.privateArmor.isEmpty, "the new key is kept natively while it waits")
		XCTAssertNil(BeamioChatPgpKeychain.load(eoa: account), "nothing is recorded until the registration is done")
	}

	func testAFailedRegistrationKeepsTheSameKeyForTheRetry() throws {
		try requireFramework()
		chain = MockChain()
		XCTAssertEqual(BeamioPGPIdentityCreate.prepare(eoa: account, idempotencyKey: "idem-f"), .ready(.first))
		fake.result = .failure(AddressPGPChain.ReadError.rpc("refused"))
		XCTAssertEqual(BeamioPGPIdentityCreate.confirm(eoa: account, idempotencyKey: "idem-f"), .retryWrite)
		let first = try XCTUnwrap(BeamioChatPgpKeychain.loadPending(eoa: account)).publicArmor
		fake.result = .success(())
		XCTAssertEqual(BeamioPGPIdentityCreate.confirm(eoa: account, idempotencyKey: "idem-f"), .ok)
		XCTAssertEqual(fake.calls.last?.publicArmor, first, "the retry registers the same key, not a new one")
	}

	func testAChangeOnChainBeforeTheConfirmationIsCASConflict() throws {
		try requireFramework()
		chain = MockChain()
		XCTAssertEqual(BeamioPGPIdentityCreate.prepare(eoa: account, idempotencyKey: "idem-x"), .ready(.first))
		chain = MockChain(exists: true, publicArmor: "someone-else", backup: "QUJD", readable: true)
		XCTAssertEqual(BeamioPGPIdentityCreate.confirm(eoa: account, idempotencyKey: "idem-x"), .casConflict)
		XCTAssertNil(BeamioChatPgpKeychain.loadPending(eoa: account), "a conflict drops the prepared state")
		XCTAssertTrue(fake.calls.isEmpty, "nothing is registered after a conflict")
	}

	func testConfirmWithAnotherKeyIsNotPrepared() throws {
		try requireFramework()
		chain = MockChain()
		XCTAssertEqual(BeamioPGPIdentityCreate.prepare(eoa: account, idempotencyKey: "idem-n"), .ready(.first))
		XCTAssertEqual(BeamioPGPIdentityCreate.confirm(eoa: account, idempotencyKey: "other"), .failed("not_prepared"))
	}

	// MARK: - Cancel

	func testCancelDropsAPreparedIdentityButNotAGeneratedKey() throws {
		try requireFramework()
		chain = MockChain()
		XCTAssertEqual(BeamioPGPIdentityCreate.prepare(eoa: account, idempotencyKey: "idem-k"), .ready(.first))
		XCTAssertTrue(BeamioPGPIdentityCreate.cancel(eoa: account))
		XCTAssertNil(BeamioChatPgpKeychain.loadPending(eoa: account))

		XCTAssertEqual(BeamioPGPIdentityCreate.prepare(eoa: account, idempotencyKey: "idem-k2"), .ready(.first))
		BeamioPGPIdentityCreate.registration = nil
		XCTAssertEqual(BeamioPGPIdentityCreate.confirm(eoa: account, idempotencyKey: "idem-k2"), .waitingRegistration)
		XCTAssertFalse(BeamioPGPIdentityCreate.cancel(eoa: account), "a generated key is kept for the registration")
		XCTAssertNotNil(BeamioChatPgpKeychain.loadPending(eoa: account))
	}

	// MARK: - Result codes

	func testTheEventCodesOfTheConfirmation() {
		XCTAssertEqual(BeamioPGPIdentityCreate.eventCode(.ok), "ok")
		XCTAssertEqual(BeamioPGPIdentityCreate.eventCode(.waitingRegistration), "waiting_registration")
		XCTAssertEqual(BeamioPGPIdentityCreate.eventCode(.retryWrite), "retry_write")
		XCTAssertEqual(BeamioPGPIdentityCreate.eventCode(.casConflict), "cas_conflict")
		XCTAssertEqual(BeamioPGPIdentityCreate.eventCode(.failed("readback_failed")), "readback_failed")
		XCTAssertNil(BeamioPGPIdentityCreate.eventCode(.failed("not_prepared")))
		// the later ruling (spec revision r3ja, line 254): already_exists is an event, with state ok (the state is added where the event is emitted)
		XCTAssertEqual(BeamioPGPIdentityCreate.eventCode(.failed("already_exists")), "already_exists")
	}

	// MARK: - Group C, C-29 (; pgp-bridge-command-vectors)

	private final class C29Store: BeamioChatWalletKeyStoring {
		var keys: [String: Data] = [:]
		func write(eoa: String, key: Data) -> Bool { keys[eoa.lowercased()] = key; return true }
		func read(eoa: String) -> Data? { keys[eoa.lowercased()] }
		func enumerateKeyOwners() -> [String]? { Array(keys.keys) }
		func delete(eoa: String) { keys[eoa.lowercased()] = nil }
		// Since the mnemonic ownership rule (Y.163 items 31 and 32) the account check lists mnemonic items; this double holds each key's account as a valid one.
		func enumerateMnemonicCreations() -> [BeamioChatKeyCreation]? { enumerateKeyOwners()?.map { BeamioChatKeyCreation(owner: $0, created: nil) } }
		func mnemonicAccountState(owner: String) -> BeamioMnemonicAccountState { (enumerateKeyOwners() ?? []).contains { $0.lowercased() == owner.lowercased() } ? .valid : .absent }
		func migrationMarkerExists(eoa: String) -> Bool { false }
		func setMigrationMarker(eoa: String) -> Bool { true }
	}

	private final class C29Records: BeamioPasscodeRecordStoring {
		func enumerateRecordOwners() -> [String]? { Array(data.keys) }
		var data: [String: Data] = [:]
		func readRecord(eoa: String) -> Data? { data[eoa.lowercased()] }
		func writeRecord(eoa: String, _ value: Data) -> Bool { data[eoa.lowercased()] = value; return true }
		func deleteRecord(eoa: String) { data[eoa.lowercased()] = nil }
	}

	private final class C29Hardware: BeamioPasscodeHardwareKeyStoring {
		var isSecureEnclave: Bool { false }
		func hasKey(eoa: String) -> Bool { true }
		func createKey(eoa: String) -> Bool { true }
		func wrap(_ plain: Data, eoa: String, aad: Data) throws -> Data { plain }
		func unwrap(_ blob: Data, eoa: String, aad: Data) throws -> Data { blob }
		func deleteKey(eoa: String) {}
	}

	/// The lock comes after the ack `accepted` (mode first) and before the chain write. No chain write happens, the ack is `accepted`, and exactly one
	/// `pgpIdentityCreateResult` with `cancelled` follows. The mock node is the first-identity chain of the group C vector.
	func testC29LockAfterAcceptedAndBeforeTheChainWriteIsCancelledOnce() throws {
		try requireFramework()
		let savedStore = BeamioNativeWallet.keyStore
		let savedVault = BeamioPasscodeSession.shared.vault
		NativeAccountPointerIsolation.begin()
		let store = C29Store()
		store.keys[account] = Data(repeating: 0x11, count: 32)
		BeamioNativeWallet.keyStore = store
		let records = C29Records()
		let passcode = BeamioPasscodeRecord(mode: "passcode", salt: Data(repeating: 1, count: 16), blob: Data(repeating: 2, count: 32))
		records.data[account] = (try? JSONEncoder().encode(passcode)) ?? Data()
		BeamioPasscodeSession.shared.vault = BeamioPasscodeVault(records: records, hardware: C29Hardware())
		BeamioPasscodeSession.shared.lockAll()
		BeamioConetChatSignBroker.setSignerEoa(account)
		BeamioConetChatModule.setNativeGateForTests(account: account, sessionReady: true)
		// the pointer first, then the session (a pointer change ends every session)
		BeamioPasscodeSession.shared.install(eoa: account, bundle: [UInt8](repeating: 0x33, count: 32))
		defer {
			BeamioPasscodeSession.shared.lockAll()
			BeamioPasscodeSession.shared.vault = savedVault
			BeamioNativeWallet.keyStore = savedStore
			BeamioConetChatSignBroker.clearSigner()
			BeamioConetChatModule.setNativeGateForTests(account: nil, sessionReady: false)
			NativeAccountPointerIsolation.end()
		}
		var events: [[String: Any]] = []
		let accepted = expectation(description: "the ack accepted")
		let resulted = expectation(description: "the result event")
		let emit: BeamioConetChatModule.WebEmit = { payload in
			guard let event = payload["event"] as? [String: Any], event["reqId"] as? String == "c3-c-29" else { return }
			events.append(event)
			if event["type"] as? String == "ack" { accepted.fulfill() }
			if event["type"] as? String == "pgpIdentityCreateResult" { resulted.fulfill() }
		}
		BeamioConetChatModule.handleCommand(
			["type": "pgpIdentityCreate", "reqId": "c3-c-29", "accountKey": account + ":default", "idempotencyKey": "idem-c-29"], emit: emit
		)
		wait(for: [accepted], timeout: 10)
		XCTAssertEqual(events.first?["ok"] as? Bool, true, "the ack is accepted")
		XCTAssertEqual((events.first?["result"] as? [String: Any])?["mode"] as? String, "first", "the mode is first")
		XCTAssertEqual((events.first?["result"] as? [String: Any])?["accepted"] as? Bool, true, "the ack carries accepted true")
		BeamioPasscodeSession.shared.lockAll()
		BeamioPGPIdentityCreate.userConfirmed(eoa: account, idempotencyKey: "idem-c-29")
		wait(for: [resulted], timeout: 10)
		XCTAssertEqual(events.filter { $0["type"] as? String == "pgpIdentityCreateResult" }.count, 1, "one result event")
		XCTAssertEqual(events.last?["code"] as? String, "cancelled", "a lock before the chain write is cancelled")
		XCTAssertEqual(fake.calls.count, 0, "no chain write happened")
		// The answers match the vector row C-29, under its own reqId.
		let differing = try GroupCVector.differences(row: try GroupCVector.row("C-29"), answers: events)
		print("GROUP-C-RUN C-29: \(differing.isEmpty ? "matches the vector" : "differs in \(differing.joined(separator: ", "))")")
		XCTAssertTrue(differing.isEmpty, "C-29: the answers differ from the vector in \(differing.joined(separator: ", "))")
	}

	/// without an approved write path the whole command answers `waiting_registration`, reading no chain and leaving nothing pending.
	func testWithoutAnApprovedWritePathTheCommandWaitsWithoutReadingTheChain() throws {
		try requireFramework()
		let restore = arrangeGroupCG2()
		defer { restore() }
		BeamioPGPIdentityCreate.registration = nil
		let savedTransport = AddressPGPChain.transport
		AddressPGPChain.transport = { [unowned self] _, _ in
			self.chainReads += 1
			return .failure(AddressPGPChain.ReadError.transport("not read"))
		}
		defer { AddressPGPChain.transport = savedTransport }
		XCTAssertEqual(BeamioPGPIdentityCreate.prepare(eoa: account, idempotencyKey: "idem-u1"), .failed("waiting_registration"))
		XCTAssertEqual(chainReads, 0, "the command reads no chain before the approval")
		XCTAssertNil(BeamioChatPgpKeychain.loadPending(eoa: account), "nothing is pending")
		sendIdentityCommand(["type": "pgpIdentityCreate", "reqId": "c3-u1", "accountKey": account + ":default", "idempotencyKey": "idem-u1"])
		let ack = identityEvents.first { $0["type"] as? String == "ack" }
		XCTAssertEqual(ack?["ok"] as? Bool, false)
		XCTAssertEqual(ack?["error"] as? String, "waiting_registration")
		XCTAssertNil(BeamioConetChatModule.identityCreateReqId, "no panel is prepared")
		XCTAssertFalse(identityEvents.contains { $0["type"] as? String == "pgpIdentityCreateResult" }, "no result event")
	}

	/// C-30 (,): not run against the vector. The write path is not approved, so the whole command answers `waiting_registration`
	/// (no chain read, no `already_exists`). The row is not counted as passed.
	func testGroupC30AnotherKeyAfterACompletedWriteWaitsForRegistration() throws {
		try requireFramework()
		let restore = arrangeGroupCG2()
		defer { restore() }
		chain = MockChain()
		sendIdentityCommand(["type": "pgpIdentityCreate", "reqId": "c3-c-30-first", "accountKey": account + ":default", "idempotencyKey": "idem-c-30-first"])
		nativeIdentityStep(.confirm, key: "idem-c-30-first")
		XCTAssertEqual(fake.calls.count, 1, "the first write happened once")
		BeamioPGPIdentityCreate.registration = nil
		identityEvents.removeAll()
		sendIdentityCommand(["type": "pgpIdentityCreate", "reqId": "c3-c-30", "accountKey": account + ":default", "idempotencyKey": "idem-c-30"])
		let ack = identityEvents.first { $0["type"] as? String == "ack" }
		XCTAssertEqual(ack?["ok"] as? Bool, false, "C-30: the write path is not approved")
		XCTAssertEqual(ack?["error"] as? String, "waiting_registration", "C-30: waiting_registration, not already_exists")
		XCTAssertEqual(fake.calls.count, 1, "C-30: no chain write")
		print("GROUP-C-NOT-RUN C-30: 未执行")
	}

	// MARK: - In-flight window

	/// The same key while the first confirmation is still open: accepted with the first mode, and no new key and no second write.
	func testAnInFlightRepeatIsAcceptedWithTheFirstModeAndWritesNothing() throws {
		try requireFramework()
		chain = MockChain()
		XCTAssertEqual(BeamioPGPIdentityCreate.prepare(eoa: account, idempotencyKey: "idem-w1"), .ready(.first))
		XCTAssertEqual(BeamioPGPIdentityCreate.prepare(eoa: account, idempotencyKey: "idem-w1"), .inFlightDuplicate(.first))
		XCTAssertEqual(BeamioPGPIdentityCreate.confirm(eoa: account, idempotencyKey: "idem-w1"), .ok)
		XCTAssertEqual(fake.calls.count, 1, "one chain write")
	}

	/// The repeat gets its own accepted and one idempotent result under its own reqId. The first request keeps the identity-create slot, so its
	/// confirmation's result goes to its own reqId, and the repeat does not change that.
	func testAnInFlightRepeatGetsItsOwnIdempotentResultAndTheFirstKeepsItsSlot() throws {
		try requireFramework()
		let restore = arrangeGroupCG2()
		defer { restore() }
		chain = MockChain()
		sendIdentityCommand(["type": "pgpIdentityCreate", "reqId": "c3-w-first", "accountKey": account + ":default", "idempotencyKey": "idem-w2"])
		XCTAssertEqual(BeamioConetChatModule.identityCreateReqId as? String, "c3-w-first")
		identityEvents.removeAll()
		sendIdentityCommand(["type": "pgpIdentityCreate", "reqId": "c3-w-repeat", "accountKey": account + ":default", "idempotencyKey": "idem-w2"])
		waitUntil { self.identityEvents.contains { $0["reqId"] as? String == "c3-w-repeat" && $0["type"] as? String == "pgpIdentityCreateResult" } }
		XCTAssertEqual(BeamioConetChatModule.identityCreateReqId as? String, "c3-w-first", "the repeat does not overwrite the first reqId")
		let repeatEvents = identityEvents.filter { $0["reqId"] as? String == "c3-w-repeat" }
		XCTAssertEqual(repeatEvents.map { $0["type"] as? String }, ["ack", "pgpIdentityCreateResult"], "one ack and one result for the repeat")
		XCTAssertEqual((repeatEvents.first?["result"] as? [String: Any])?["mode"] as? String, "first", "the repeat carries the first mode")
		XCTAssertEqual(repeatEvents.last?["code"] as? String, "idempotent")
		XCTAssertEqual(fake.calls.count, 0, "the repeat writes nothing")
		BeamioPGPIdentityCreate.userConfirmed(eoa: account, idempotencyKey: "idem-w2")
		waitUntil { self.identityEvents.contains { $0["reqId"] as? String == "c3-w-first" && $0["type"] as? String == "pgpIdentityCreateResult" } }
		let firstResults = identityEvents.filter { $0["reqId"] as? String == "c3-w-first" && $0["type"] as? String == "pgpIdentityCreateResult" }
		XCTAssertEqual(firstResults.count, 1, "the first request has one result")
		XCTAssertEqual(firstResults.first?["code"] as? String, "ok", "the first confirmation's result goes to the first reqId")
		XCTAssertEqual(fake.calls.count, 1, "one chain write, for the first request")
	}

	/// After a cancel the window is closed: the same key is prepared again, not answered as a repeat.
	func testAfterACancelTheSameKeyIsPreparedAgain() throws {
		try requireFramework()
		chain = MockChain()
		XCTAssertEqual(BeamioPGPIdentityCreate.prepare(eoa: account, idempotencyKey: "idem-c1"), .ready(.first))
		XCTAssertTrue(BeamioPGPIdentityCreate.cancel(eoa: account))
		XCTAssertEqual(BeamioPGPIdentityCreate.prepare(eoa: account, idempotencyKey: "idem-c1"), .ready(.first))
	}

	/// After a failed write (`retry_write`) the same key is retried with a native confirmation, and writes again. It is not answered as idempotent.
	func testAfterAWriteFailureTheSameKeyIsRetriedAndWritesAgain() throws {
		try requireFramework()
		chain = MockChain()
		XCTAssertEqual(BeamioPGPIdentityCreate.prepare(eoa: account, idempotencyKey: "idem-r1"), .ready(.first))
		fake.result = .failure(AddressPGPChain.ReadError.rpc("refused"))
		XCTAssertEqual(BeamioPGPIdentityCreate.confirm(eoa: account, idempotencyKey: "idem-r1"), .retryWrite)
		XCTAssertEqual(BeamioPGPIdentityCreate.prepare(eoa: account, idempotencyKey: "idem-r1"), .ready(.first), "a retry is a prepare, not a repeat")
		fake.result = .success(())
		XCTAssertEqual(BeamioPGPIdentityCreate.confirm(eoa: account, idempotencyKey: "idem-r1"), .ok)
		XCTAssertEqual(fake.calls.count, 2, "the retry writes")
	}

	/// After a waiting registration the same key is prepared again, and the confirmation writes once the registration is there.
	func testAfterAWaitingRegistrationTheSameKeyIsPreparedAgain() throws {
		try requireFramework()
		chain = MockChain()
		let saved = BeamioPGPIdentityCreate.registration
		XCTAssertEqual(BeamioPGPIdentityCreate.prepare(eoa: account, idempotencyKey: "idem-n1"), .ready(.first))
		BeamioPGPIdentityCreate.registration = nil
		XCTAssertEqual(BeamioPGPIdentityCreate.confirm(eoa: account, idempotencyKey: "idem-n1"), .waitingRegistration)
		BeamioPGPIdentityCreate.registration = saved
		XCTAssertEqual(BeamioPGPIdentityCreate.prepare(eoa: account, idempotencyKey: "idem-n1"), .ready(.first), "prepared again, not a repeat")
		XCTAssertEqual(BeamioPGPIdentityCreate.confirm(eoa: account, idempotencyKey: "idem-n1"), .ok)
		XCTAssertEqual(fake.calls.count, 1, "the registration is written once")
	}

	/// A confirmation that arrives while a chain write is running for the account does not write again (one write at a time).
	func testAConfirmDuringAWriteDoesNotWriteAgain() throws {
		try requireFramework()
		chain = MockChain()
		XCTAssertEqual(BeamioPGPIdentityCreate.prepare(eoa: account, idempotencyKey: "idem-x1"), .ready(.first))
		XCTAssertTrue(BeamioPGPIdentityCreate.beginWrite(eoa: account), "a write starts")
		XCTAssertEqual(BeamioPGPIdentityCreate.confirm(eoa: account, idempotencyKey: "idem-x1"), .idempotent)
		BeamioPGPIdentityCreate.endWrite(eoa: account)
		XCTAssertTrue(fake.calls.isEmpty, "no write during the running write")
	}

	// MARK: - Group C, C-10 to C-20 (; pgp-bridge-command-vectors), through the bridge with the native step

	/// The native step after the ack: the user confirms, the user cancels, or the 120-second confirmation times out.
	private enum NativeStep { case confirm, cancel, timeout }

	/// The registered digest of `pgp-bridge-command-vectors.v1.json`. The same pin as PGPBridgeGroupCTests.
	private static let bridgeVectorSHA256 = "40ac9784730ddbdda5ed5cce96269973f833db90acd6c9073e890367a77280d6"

	/// One row of group C, read from the registered vector file. The digest is checked, not printed.
	private func groupCRow(_ id: String) throws -> [String: Any] {
		guard let path = ProcessInfo.processInfo.environment["PGP_BRIDGE_VECTORS"] else {
			throw XCTSkip("set PGP_BRIDGE_VECTORS to interface/protocol/pgp-bridge-command-vectors.v1.json")
		}
		let data = try Data(contentsOf: URL(fileURLWithPath: path))
		XCTAssertTrue(SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined() == Self.bridgeVectorSHA256,
		              "the pgp-bridge vector file differs from the registered digest (the digest is not printed)")
		let root = try XCTUnwrap(JSONSerialization.jsonObject(with: data) as? [String: Any])
		let cases = try XCTUnwrap(root["cases"] as? [[String: Any]])
		return try XCTUnwrap(cases.first { $0["id"] as? String == id }, id)
	}

	/// G2 for the account with no passcode and nothing locked: the arrangement of the group C runner for G2.
	private func arrangeGroupCG2() -> () -> Void {
		let savedStore = BeamioNativeWallet.keyStore
		let savedVault = BeamioPasscodeSession.shared.vault
		NativeAccountPointerIsolation.begin()
		let store = C29Store()
		store.keys[account] = Data(repeating: 0x11, count: 32)
		BeamioNativeWallet.keyStore = store
		BeamioPasscodeSession.shared.vault = BeamioPasscodeVault(records: C29Records(), hardware: C29Hardware())
		BeamioPasscodeSession.shared.lockAll()
		BeamioConetChatSignBroker.setSignerEoa(account)
		BeamioConetChatModule.setNativeGateForTests(account: account, sessionReady: true)
		BeamioConetChatModule.identityCreateReqId = nil
		return {
			BeamioPasscodeSession.shared.lockAll()
			BeamioPasscodeSession.shared.vault = savedVault
			BeamioNativeWallet.keyStore = savedStore
			BeamioConetChatSignBroker.clearSigner()
			BeamioConetChatModule.setNativeGateForTests(account: nil, sessionReady: false)
			BeamioConetChatModule.identityCreateReqId = nil
			NativeAccountPointerIsolation.end()
		}
	}

	/// Spins the main run loop until the condition holds, or ten seconds pass.
	private func waitUntil(_ condition: () -> Bool) {
		let deadline = Date().addingTimeInterval(10)
		while !condition() && Date() < deadline {
			RunLoop.main.run(until: Date().addingTimeInterval(0.02))
		}
	}

	/// Sends one `pgpIdentityCreate` through the bridge and waits for its ack. Every event the bridge emits is kept in `identityEvents`, in order. The
	/// bridge's emit channel is replaced by each command (`handleCommand` sets it), so events of an earlier command are captured here, not by a closure.
	private func sendIdentityCommand(_ body: [String: Any]) {
		let reqId = body["reqId"] as? String ?? ""
		BeamioConetChatModule.handleCommand(body) { payload in
			if let event = payload["event"] as? [String: Any] {
				self.identityEvents.append(event)
			}
		}
		waitUntil { self.identityEvents.contains { $0["type"] as? String == "ack" && $0["reqId"] as? String == reqId } }
	}

	/// The native step for a prepared identity, then the wait for its one `pgpIdentityCreateResult`.
	private func nativeIdentityStep(_ step: NativeStep, key: String) {
		switch step {
		case .confirm: BeamioPGPIdentityCreate.userConfirmed(eoa: account, idempotencyKey: key)
		case .cancel: BeamioPGPIdentityCreate.userCancelled(eoa: account)
		case .timeout: BeamioPGPIdentityCreate.userCancelled(eoa: account, timedOut: true)
		}
		waitUntil { self.identityEvents.contains { $0["type"] as? String == "pgpIdentityCreateResult" } }
	}

	/// Compares the ack and the events for one row with the vector, through the shared comparator (keys included). Returns the differences, or nil.
	private func rowMismatch(row: [String: Any]) throws -> String? {
		let differing = try GroupCVector.differences(row: row, answers: identityEvents)
		return differing.isEmpty ? nil : differing.joined(separator: ", ")
	}

	/// C-10: a record without a backup is replaced after the native confirmation. One chain write, answered `ok`.
	func testGroupC10ReplaceConfirmedWritesOnce() throws {
		try requireFramework()
		let restore = arrangeGroupCG2()
		defer { restore() }
		let row = try groupCRow("C-10")
		chain = MockChain(exists: true, publicArmor: "-----BEGIN PGP PUBLIC KEY BLOCK-----\narmor-1\n-----END PGP PUBLIC KEY BLOCK-----", backup: "", readable: true)
		sendIdentityCommand(try XCTUnwrap(row["request"] as? [String: Any]))
		nativeIdentityStep(.confirm, key: "idem-c-10")
		let mismatch = try rowMismatch(row: row)
		print("GROUP-C-RUN C-10: \(mismatch == nil ? "matches the vector" : "differs: \(mismatch!)")")
		XCTAssertNil(mismatch, "C-10: the answer matches the vector")
		XCTAssertEqual(fake.calls.count, 1, "C-10: one chain write")
	}

	/// C-11: a replacement the user cancels on the native panel. Nothing is written, on chain or locally.
	func testGroupC11ReplaceCancelledWritesNothing() throws {
