	/// C-13: the chain changes after the ack and before the user confirms. The first CAS fails: no key is generated and nothing is written.
	func testGroupC13ChainChangeBeforeTheConfirmationIsCASConflict() throws {
		try requireFramework()
		let restore = arrangeGroupCG2()
		defer { restore() }
		let row = try groupCRow("C-13")
		let savedGen = savedGenerate!
		BeamioPGPIdentityCreate.generateKeyPair = { [unowned self] eoa in
			self.generatedCount += 1
			return savedGen(eoa)
		}
		defer { BeamioPGPIdentityCreate.generateKeyPair = savedGen }
		chain = MockChain(exists: true, publicArmor: "-----BEGIN PGP PUBLIC KEY BLOCK-----\narmor-1\n-----END PGP PUBLIC KEY BLOCK-----", backup: "", readable: true)
		sendIdentityCommand(try XCTUnwrap(row["request"] as? [String: Any]))
		chain = MockChain(exists: true, publicArmor: "someone-else", backup: "QUJD", readable: true)
		nativeIdentityStep(.confirm, key: "idem-c-13")
		let mismatch = try rowMismatch(row: row)
		print("GROUP-C-RUN C-13: \(mismatch == nil ? "matches the vector" : "differs: \(mismatch!)")")
		XCTAssertNil(mismatch, "C-13: the answer matches the vector")
		XCTAssertEqual(generatedCount, 0, "C-13: no key is generated")
		XCTAssertTrue(fake.calls.isEmpty, "C-13: nothing is written")
	}

	/// C-14: the chain changes after the key is generated and before the write. The second CAS fails: the pending key is dropped and nothing is written.
	func testGroupC14ChainChangeBeforeTheWriteIsCASConflict() throws {
		try requireFramework()
