	/// the completed key is answered with the mode of its own write, and the confirmation says `idempotent` with no second write.
	func testACompletedFirstIdentityIsAcceptedAgainAsFirstAndIdempotent() throws {
		try requireFramework()
		chain = MockChain()
		XCTAssertEqual(BeamioPGPIdentityCreate.prepare(eoa: account, idempotencyKey: "idem-f1"), .ready(.first))
		XCTAssertEqual(BeamioPGPIdentityCreate.confirm(eoa: account, idempotencyKey: "idem-f1"), .ok)
		XCTAssertEqual(BeamioPGPIdentityCreate.prepare(eoa: account, idempotencyKey: "idem-f1"), .ready(.first))
		XCTAssertEqual(BeamioPGPIdentityCreate.confirm(eoa: account, idempotencyKey: "idem-f1"), .idempotent)
		XCTAssertEqual(BeamioPGPIdentityCreate.eventCode(.idempotent), "idempotent")
		XCTAssertEqual(fake.calls.count, 1, "one chain write")
		// another key is not answered from memory; it reads the chain like any prepare. The device now holds the identity that was just written, so the
		// native first-identity judgement (frozen protocol §13) refuses a second first identity: legacy is PRESENT.
		XCTAssertEqual(BeamioPGPIdentityCreate.prepare(eoa: account, idempotencyKey: "idem-other"), .failed("not_eligible"),
		               "another key after a completed write: this device already holds a chat key")
	}

	/// C-15: the same idempotency key again after a completed write. The command is accepted with the mode of that write, and the confirmation answers
	/// `idempotent`, with no second chain write.
	func testGroupC15SameKeyAfterACompletedWriteIsIdempotent() throws {
		try requireFramework()
		let restore = arrangeGroupCG2()
		defer { restore() }
		let row = try groupCRow("C-15")
		chain = MockChain(exists: true, publicArmor: "-----BEGIN PGP PUBLIC KEY BLOCK-----\narmor-1\n-----END PGP PUBLIC KEY BLOCK-----", backup: "", readable: true)
		let key = "idem-c-15"
		sendIdentityCommand(["type": "pgpIdentityCreate", "reqId": "c3-c-15-first", "accountKey": account + ":default", "idempotencyKey": key])
		nativeIdentityStep(.confirm, key: key)
		XCTAssertEqual(fake.calls.count, 1, "the first write happened once")
		identityEvents.removeAll()
		sendIdentityCommand(try XCTUnwrap(row["request"] as? [String: Any]))
		nativeIdentityStep(.confirm, key: key)
		let mismatch = try rowMismatch(row: row)
		print("GROUP-C-RUN C-15: \(mismatch == nil ? "matches the vector" : "differs: \(mismatch!)")")
		XCTAssertNil(mismatch, "C-15: the answer matches the vector")
		XCTAssertEqual(fake.calls.count, 1, "C-15: no second chain write")
	}

